const cwNumber=(id,label,target,max=90)=>({id,label,kind:'number',target,max,points:1});
const cwQuarters=(prefix)=>[['nw','Nordwestviertel'],['no','Nordostviertel'],['sw','Südwestviertel'],['so','Südostviertel']].map(([code,text],i)=>cwText(prefix+i,`${i+1}. ${prefix==='cross'?(i<2?'oben':'unten')+' '+(i%2?'rechts':'links'):'Bereich '+(i+1)}`,[text,code]));
const cwBoards={latSide:['Breitenkreise · Seitenansicht','circle'],latPole:['Breitenkreise · Draufsicht auf den Pol','circle'],lonSide:['Meridiane · Seitenansicht','circle'],lonPole:['Meridiane · Draufsicht auf den Pol','circle'],gLat:['a) Breitenkreise einzeichnen','circle'],gLon:['b) Meridiane einzeichnen','circle'],gBoth:['c) Beide Linienarten und Schnittpunkt','circle']};
